import { BlueprintWordmark as SharedBlueprintWordmark } from "@blueprint/ui";
import type { SVGProps } from "react";
import {
  Layers,
  Paintbrush,
  Radius,
  Ruler,
  Settings,
  Type,
} from "lucide-react";
import styles from "./shell-marks.module.css";

type MarkProps = SVGProps<SVGSVGElement>;

/**
 * Shared drawing attributes for the custom rail marks.
 *
 * Width and height stay off this object: SideNav wraps component icons in
 * `Icon`. Row size is `lg`; item glyphs are still passed as `sm` internally,
 * so globals.css sizes them to Icon lg (1.5rem).
 */
const mark = {
  fill: "none",
  stroke: "currentColor",
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
  strokeWidth: 2,
  viewBox: "0 0 24 24",
};

/** The Blueprint B — Home on the rail. */
export function BlueprintMark(props: MarkProps) {
  return (
    <svg aria-hidden fill="none" viewBox="0 0 104 174" {...props}>
      <path
        d="M-1.02209 43.1729C8.46287 53.1485 42.805 47.0977 62.4291 47.0977C76.1747 47.0978 87.6136 55.6019 87.6136 68.3575C87.6135 83.7294 78.7821 87.9812 72.8949 90.5977C103.803 98.7744 103.64 148.325 40.1888 148.325C7.31854 148.325 0.558732 135.787 -1.02209 130.336V43.1729ZM59.3217 71.7911C59.3214 54.9477 39.0442 57.5635 26.9427 57.5636V132.953C39.317 132.353 64.0648 127.033 64.0648 110.549C64.0648 94.0647 50.8726 90.816 44.2767 91.252C49.2918 90.3799 59.3217 85.2663 59.3217 71.7911Z"
        fill="currentColor"
      />
      <path
        d="M41.3331 33.1974C41.3331 37.352 32.0346 40.7199 20.5643 40.7199C9.09404 40.7199 -0.204468 37.352 -0.204468 33.1974C-0.204468 29.0428 9.09404 25.6748 20.5643 25.6748C32.0346 25.6748 41.3331 29.0428 41.3331 33.1974Z"
        fill="currentColor"
      />
    </svg>
  );
}

/**
 * The Blueprint wordmark — Home TopNav.
 *
 * The drawing lives in `@blueprint/ui` now that the documentation site needs
 * the same one; what stays here is the rail's sizing, which is this
 * application's and not the mark's.
 */
export function BlueprintWordmark(props: MarkProps) {
  return (
    <SharedBlueprintWordmark
      {...props}
      className={`${styles.wordmark} ${props.className ?? ""}`}
    />
  );
}

